```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?nba_season ?team
WHERE {
  # Team currently coached by Brad Stevens
  ?team ns:basketball.basketball_team.head_coach ns:m.02qwvmq .

  # In which NBA seasons did this team win the championship
  ?team ns:sports.sports_team.championships ?nba_season .

  # Find teams with Brad Stevens as head coach that played in 2010 NBA finals (champion or runner-up)
  {
    ?finals_2010 ns:sports.sports_championship_event.championship_season "2010" .
    { ?finals_2010 ns:sports.sports_championship_event.champion ?team . }
    UNION
    { ?finals_2010 ns:sports.sports_championship_event.runner_up ?team . }
  }

  # Teams that Rasheed Wallace was on whose head coach is Brad Stevens
  # Rasheed Wallace id: ns:m.02hdjz
  OPTIONAL {
    ns:m.02hdjz ns:sports.pro_athlete.teams ?team_roster .
    ?team_roster ns:sports.sports_team_roster.team ?team .
    ?team ns:basketball.basketball_team.head_coach ns:m.02qwvmq .
  }
}
