    ns:m.0by0ww1 ns:sports.sports_championship_event.champion ?team .
  }
  UNION
  {
    ns:m.0by0ww1 ns:sports.sports_championship_event.runner_up ?team .
  }
  # Optional: teams having Tommy Hawk as mascot (for first question)
  OPTIONAL { ?team ns:sports.sports_team.team_mascot ns:m.0j2bv42 . }

