  OPTIONAL {
    ?team ns:sports.sports_team.team_mascot ?mascotOldName .
    ?mascotOldName ns:sports.sports_team.previously_known_as ns:m.0100sszz .
  }

  # Teams that Hank Baskett was on in 2010 and whose stadium is the Hubert H. Humphrey Metrodome (Q3)
  OPTIONAL {
    ns:m.0d81yf ns:sports.pro_athlete.teams ?roster .
    ?roster ns:sports.sports_team_roster.team ?team .
    FILTER (
      (!BOUND(?roster) || !BOUND(?rosterFrom) || !BOUND(?rosterTo)) ||
      (
        (NOT EXISTS { ?roster ns:sports.sports_team_roster.from ?rosterFrom }) || 
        (EXISTS { ?roster ns:sports.sports_team_roster.from ?fromVal . FILTER(xsd:dateTime(?fromVal) <= "2010-12-31T23:59:59"^^xsd:dateTime) })
