```sparql
PREFIX ns: <http://rdf.freebase.com/ns/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?x
WHERE {
  ns:m.081pw ns:time.event.start_date ?start ;
             ns:time.event.end_date ?end .
  ?x ns:government.politician.government_positions_held ?y .
  ?y ns:government.government_position_held.office_position_or_title ns:m.060d2 ;
     ns:government.government_position_held.from ?from ;
     ns:government.government_position_held.to ?to .
  FILTER (?from < ?end) .
  FILTER (?to > ?start) .

  # Match the three cases
  {
    # Case 1: Held position from 1933-03-05 and was president during WWII
    FILTER EXISTS { ?y ns:government.government_position_held.from "1933-03-05"^^xsd:dateTime }
  }
  UNION
  {
    # Case 2: Held position until 1933-12-31 and was president during WWII
    FILTER EXISTS { ?y ns:government.government_position_held.to "1933-12-31"^^xsd:dateTime }
  }
  UNION
  {
    # Case 3: Started government position before 1939-01-02 and was president during WWII
    FILTER (?from < "1939-01-02"^^xsd:dateTime)
  }
}
```

