  {
    # Query 2: What member of John F. Kennedy's family wrote "The Riverkeepers"?
    ?relative (ns:people.person.parents|ns:people.person.children|ns:people.person.sibling_s/ns:people.sibling_relationship.sibling|ns:people.person.spouse_s/ns:people.marriage.spouse) ?relativeMember .
