    BIND(?relative AS ?answer)
    ns:m.0d3k14 ?rel ?relative .
    ?answer ns:book.author.works_written ns:m.05xhqq .
    FILTER EXISTS {
      { ns:m.0d3k14 ns:people.person.parents ?relative . }
      UNION
      { ns:m.0d3k14 ns:people.person.children ?relative . }
      UNION
      {
        ns:m.0d3k14 ns:people.person.sibling_s ?sib .
        ?sib ns:people.sibling_relationship.sibling ?relative .
      }
      UNION
      {
        ns:m.0d3k14 ns:people.person.spouse_s ?sp .
        ?sp ns:people.marriage.spouse ?relative .
        ?sp ns:people.marriage.type_of_union ns:m.04ztj .
        FILTER (NOT EXISTS {?sp ns:people.marriage.to []})
      }
