PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?country_with_iso_012 ?border_country_gt_524 ?trading_partner_largest_iso WHERE {
  {
    # What country has the ISO number 012 and is a trading partner of China?
    FILTER (?country_with_iso_012 != ns:m.0d05w3)
    {
      ns:m.0d05w3 ns:location.statistical_region.places_exported_to ?y1 .
      ?y1 ns:location.imports_and_exports.exported_to ?country_with_iso_012 .
    }
    UNION
    {
      ns:m.0d05w3 ns:location.statistical_region.places_imported_from ?y2 .
      ?y2 ns:location.imports_and_exports.imported_from ?country_with_iso_012 .
    }
    ?country_with_iso_012 ns:location.country.iso_numeric "012" .
  }
  UNION
  {
    # What countries does China border that have ISO numerics greater than 524?
    FILTER (?border_country_gt_524 != ns:m.0d05w3)
    ns:m.0d05w3 ns:location.location.adjoin_s ?adjacent_region .
    ?adjacent_region ns:location.adjoining_relationship.adjoins ?border_country_gt_524 .
    ?border_country_gt_524 ns:location.country.iso_numeric ?iso_numeric_gt_524 .
    FILTER (xsd:integer(?iso_numeric_gt_524) > 524)
  }
  UNION
  {
    # What trading part of China has the largest ISO numeric code?
    FILTER (?trading_partner_largest_iso != ns:m.0d05w3)
    {
      ns:m.0d05w3 ns:location.statistical_region.places_exported_to ?y3 .
      ?y3 ns:location.imports_and_exports.exported_to ?trading_partner_largest_iso .
