```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?answer1 ?answer2 ?answer3 WHERE {
  # Answer 1: In 2012, to whom was the actor who portrayed the character Barbara Fordham married?
  {
    SELECT ?answer1 WHERE {
      ?actor ns:film.performance.character ns:m.0j14zfr .  # Barbara Fordham character
      ?actor ns:people.person.spouse_s ?marriage .
      ?marriage ns:people.marriage.spouse ?answer1 .
      ?marriage ns:people.marriage.type_of_union ns:m.04ztj .
      ?marriage ns:people.marriage.from ?fromDate .
      FILTER(year(xsd:dateTime(?fromDate)) <= 2012)
    }
    ORDER BY DESC(?fromDate)
    LIMIT 1
  }

  # Answer 2: What country bordering the US that the character Meredith Gordon resided?
  {
    SELECT ?answer2 WHERE {
      FILTER(?answer2 != ns:m.09c7w0)  # Exclude US itself
      ns:m.09c7w0 ns:location.location.adjoin_s ?borderRelation .
      ?borderRelation ns:location.adjoining_relationship.adjoins ?answer2 .
      ?answer2 ns:common.topic.notable_types ns:m.01mp .        # notable country
      ?answer2 ns:fictional_universe.fictional_setting.characters_that_have_lived_here ns:m.121bwm8p .  # Meredith Gordon
    }
    LIMIT 1
  }

  # Answer 3: What actor played LBaine in Batman and also wrote the film, the Last White Dishwasher?
  {
    SELECT ?answer3 WHERE {
      { 
        ns:m.0321b4 ns:film.film_character.portrayed_in_films ?filmChar .
        ?filmChar ns:film.performance.actor ?answer3 .
      }
      UNION
      {
        ns:m.0321b4 ns:tv.tv_character.appeared_in_tv_program ?tvProg .
        ?tvProg ns:tv.regular_tv_appearance.actor ?answer3 .
      }
      ?answer3 ns:film.writer.film ns:m.06w44rw .
    }
    LIMIT 1
  }
}
```

