```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?war
WHERE {
  {
    # George Washington's wars with casualty lower estimate 400
    ns:m.034rd ns:military.military_commander.military_commands ?command .
    ?command ns:military.military_command.military_conflict ?war .
    ?war ns:military.military_conflict.casualties ?casualties .
    ?casualties ns:military.casualties.lower_estimate "400" .
  }
  UNION
  {
    # War with George Washington with the lowest number of casualties
    {
      SELECT ?warWithLowCasualty WHERE {
        ns:m.034rd ns:military.military_commander.military_commands ?cmd .
        ?cmd ns:military.military_command.military_conflict ?warWithLowCasualty .
        ?warWithLowCasualty ns:military.military_conflict.casualties ?casualtyNode .
        ?casualtyNode ns:military.casualties.lower_estimate ?num .
      }
      ORDER BY xsd:integer(?num)
      LIMIT 1
    } BIND(?warWithLowCasualty AS ?war)
  }
  UNION
  {
    # Wars during Woodrow Wilson presidency with casualty lower estimate < 885138
    {
      SELECT ?pfrom ?pto WHERE {
        ns:m.083q7 ns:government.politician.government_positions_held ?pos .
        ?pos ns:government.government_position_held.basic_title ns:m.060c4 ; # President
             ns:government.government_position_held.from ?pfrom ;
             ns:government.government_position_held.to ?pto .
      }
      LIMIT 1
    }
    ?war ns:common.topic.notable_types ns:m.02h76fz . # Military Conflict
    ?war ns:time.event.start_date ?from .
    ?war ns:time.event.end_date ?to .
    FILTER (?from >= ?pfrom && ?to <= ?pto)
    ?war ns:military.military_conflict.casualties ?c .
    ?c ns:military.casualties.lower_estimate ?num .
    FILTER (xsd:integer(?num) < 885138)
  }
}
